import { WindowConf } from '@droid/android';
import { useProxyWatch, useTranslation } from '@fanfanlo';
import { Box, Stack, TextField } from '@mui/material';
import { OptionalLabel } from './WindowConfUI';

export interface AdvancedSectionProps {
  windowConf: WindowConf;
}

/**
 * AdvancedSection - 高级选项编辑区域
 *
 * 编辑字段：
 * - forceDismissWindowTime: 强制关闭时间
 */
export function AdvancedSection({ windowConf }: AdvancedSectionProps) {
  const { t } = useTranslation('homepage/components/android-float/window/content');
  const [forceDismissWindowTime] = useProxyWatch(
    windowConf,
    'forceDismissWindowTime',
    windowConf.forceDismissWindowTime
  );

  console.log('AdvancedSection: render forceDismissWindowTime:', forceDismissWindowTime);

  return (
    <Stack spacing={2}>
      {/* 强制关闭时间 */}
      <Box>
        <OptionalLabel label={t('AdvancedSection.forceDismissWindowTimeLabel')} />
        <TextField
          type="number"
          value={forceDismissWindowTime}
          onChange={(e) => {
            console.log('AdvancedSection: forceDismissWindowTime changed to', e.target.value);
            windowConf.forceDismissWindowTime = Number(e.target.value);
          }}
          size="small"
          fullWidth
          inputProps={{ min: 0, step: 1000 }}
          helperText={t('AdvancedSection.forceDismissWindowTimeHelper')}
        />
      </Box>
    </Stack>
  );
}
